const things=[];for(const e of enemies)if(e.alive)things.push({type:'enemy',x:e.x,y:e.y,e});if(!alarm){things.push({type:'gate',x:8.1,y:1.55})}else things.push({type:'exit',x:8.1,y:1.55});things.sort((a,b)=>Math.hypot(b.x-player.x,b.y-player.y)-Math.hypot(a.x-player.x,a.y-player.y));for(const o of things){let dx=o.x-player.x,dy=o.y-player.y,dist=Math.hypot(dx,dy),ang=Math.atan2(dy,dx)-player.a;ang=Math.atan2(Math.sin(ang),Math.cos(ang));if(Math.abs(ang)>FOV*.7||dist<.1)continue;let sx=W*(.5+ang/FOV),col=Math.floor(sx/3);if(col<0||col>=zbuf.length||dist>zbuf[col]+.2)continue;let size=Math.min(H*1.1,H/(dist*.9)),cy=horizon+size*.03;if(o.type==='enemy')drawEnemy(sx,cy,size,o.e,dist);else drawGate(sx,cy,size,alarm)}
