function drawGate(sx,cy,size,isOpen){let w=size*.65,h=size*.9;ctx.save();ctx.translate(sx,cy);ctx.fillStyle='#202832';ctx.fillRect(-w/2,-h/2,w,h);ctx.strokeStyle=isOpen?'#5df6d9':'#ff4855';ctx.lineWidth=Math.max(2,size*.025);ctx.shadowColor=ctx.strokeStyle;ctx.shadowBlur=25;ctx.strokeRect(-w*.42,-h*.46,w*.84,h*.92);ctx.fillStyle=isOpen?'#50e5d622':'#ef394422';ctx.fillRect(-w*.36,-h*.4,w*.72,h*.8);for(let i=-2;i<=2;i++){ctx.fillStyle=isOpen?'#79ffdf':'#ff5665';ctx.fillRect(i*w*.14-1,-h*.35,2,h*.7)}ctx.fillStyle='#e7e5d9';ctx.font=`bold ${Math.max(8,size*.075)}px monospace`;ctx.textAlign='center';ctx.fillText(isOpen?'ELEVADOR':'BLOQUEADO',0,-h*.55);ctx.restore()}
function beginAlarm(){alarm=true;timeLeft=120;player.heat=Math.max(52,player.heat);document.querySelector('#flash').classList.add('active');toast('ALARME! NÚCLEO EM CONTAGEM');sound(880,.4,'sawtooth',.09);setTimeout(()=>sound(660,.4,'sawtooth',.08),450);setTimeout(()=>sound(880,.4,'sawtooth',.08),900);updateHUD()}
function updateHUD(){document.querySelector('#hp').textContent=Math.ceil(player.hp);document.querySelector('#temp').textContent=Math.ceil(player.heat)+'°';document.querySelector('#kills').textContent=player.kills;document.querySelector('#heatfill').style.width=player.heat+'%';document.querySelector('#timer').innerHTML=alarm?`${String(Math.floor(timeLeft/60)).padStart(2,'0')}:${String(Math.ceil(timeLeft%60)).padStart(2,'0')}<small>FUGA / SUPERAQUECIMENTO</small>`:'02:00<small>ALARME INATIVO</small>';document.querySelector('#objective').innerHTML=alarm?'ALCANCE O ELEVADOR <em>ANTES DO COLAPSO</em>':`SETOR 01 — LIMPE A CÂMARA <em>${player.kills} / 8</em>`}
function finish(success){running=false;won=success;if(document.exitPointerLock)document.exitPointerLock();document.querySelector('#flash').classList.remove('active');document.querySelector('#overlay').style.display='grid';const p=document.querySelector('.panel');p.innerHTML=success?`<div class="eyebrow">NEXUS // EXTRAÇÃO CONFIRMADA</div><h1>VOCÊ<br><span>ESCAPOU.</span></h1><p class="desc">O elevador selou no último segundo. Núcleo a <b class="warning">${Math.ceil(player.heat)}°</b>. ${player.kills} ameaças eliminadas. O complexo ficou para trás — por enquanto.</p><div class="controls"><div><b>RESULTADO</b> extração bem-sucedida</div><div><b>ELIMINAÇÕES</b> ${player.kills} / 8</div><div><b>TEMPERATURA</b> ${Math.ceil(player.heat)}°</div><div><b>INTEGRIDADE</b> ${Math.ceil(player.hp)}%</div></div><button class="start" onclick="location.reload()">JOGAR NOVAMENTE →</button>`:`<div class="eyebrow warning">NEXUS // SINAL PERDIDO</div><h1>NÚCLEO<br><span>EM COLAPSO</span></h1><p class="desc">A temperatura crítica venceu. A instalação foi selada com você dentro. Reinicie e encontre uma rota mais rápida.</p><div class="controls"><div><b>ELIMINAÇÕES</b> ${player.kills} / 8</div><div><b>INTEGRIDADE</b> ${Math.ceil(player.hp)}%</div></div><button class="start" onclick="location.reload()">TENTAR DE NOVO →</button>`}
function update(dt){if(!running)return;player.shot=Math.max(0,player.shot-dt);if(toastTimer>0){toastTimer-=dt;if(toastTimer<=0)document.querySelector('#toast').style.opacity=0}let f=(keys.KeyW?1:0)-(keys.KeyS?1:0)+(-joy.y),s=(keys.KeyD?1:0)-(keys.KeyA?1:0)+joy.x;let mag=Math.hypot(f,s);if(mag>1){f/=mag;s/=mag}let speed=3.1;if(keys.ShiftLeft||keys.ShiftRight||player.dash>0){if(player.dash<=0)dash();speed=8.5;player.dash=Math.max(0,player.dash-dt)}let vx=(Math.cos(player.a)*f-Math.sin(player.a)*s)*speed*dt,vy=(Math.sin(player.a)*f+Math.cos(player.a)*s)*speed*dt;move(player.x+vx,player.y+vy);if(mouseDown||keys.Space)shoot();if(alarm){timeLeft-=dt;player.heat+=dt*0.19;if(timeLeft<30&&Math.random()<dt*2)sound(750,.07,'square',.012)}else player.heat=Math.max(30,player.heat-dt*.24);
for(const e of enemies){if(!e.alive)continue;e.phase+=dt*2;e.attack-=dt;let dx=player.x-e.x,dy=player.y-e.y,d=Math.hypot(dx,dy);if(d>1.3){let sp=(d<4?.3:.75)*dt,ex=dx/d*sp,ey=dy/d*sp;if(!wall(e.x+ex,e.y))e.x+=ex;if(!wall(e.x,e.y+ey))e.y+=ey}if(d<7&&e.attack<=0&&rayBlocked(e.x,e.y,player.x,player.y)===false){e.attack=1.35+Math.random()*.55;player.hp-=5;player.heat+=1.3;burst(player.x+Math.cos(player.a)*.5,player.y+Math.sin(player.a)*.5,'#ffb239',5);sound(65,.08,'square',.03)}}
for(const p of particles){p.x+=p.vx*dt;p.y+=p.vy*dt;p.life-=dt;p.vx*=.96;p.vy*=.96}particles=particles.filter(p=>p.life>0);let exitD=Math.hypot(player.x-8.1,player.y-1.55);if(!alarm&&player.kills>=8&&exitD<2.1)beginAlarm();if(alarm&&exitD<.75){finish(true);return}if(player.hp<=0||player.heat>=100||timeLeft<=0){finish(false);return}updateHUD()}

